INSERT INTO _migration_462_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_env_b002_001', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following is the safest source of drinking water for a community?', 'multiple_choice', NULL, '["A. Treated pipe-borne water","B. Stream water","C. Pond water","D. Flood water"]', 'A', 'Treated pipe-borne water has been filtered and disinfected before distribution, so it is the safest source; streams, ponds and flood water are exposed to faecal contamination, parasites and chemical pollutants and must be treated before drinking. Therefore the correct answer is A: Treated pipe-borne water.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_env_b002_002', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Boiling drinking water for several minutes makes it safe mainly by', 'multiple_choice', NULL, '["A. adding chlorine to the water","B. killing germs as heat destroys their enzymes and proteins","C. removing all dissolved minerals","D. increasing the oxygen content of the water"]', 'B', 'Boiling denatures the enzymes and structural proteins of bacteria, viruses and parasite cysts, killing them without any chemical additive; it does not add chlorine, remove dissolved minerals or meaningfully change the oxygen content. Therefore the correct answer is B: killing germs as heat destroys their enzymes and proteins.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_env_b002_003', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following is a common pollutant of river water in Ghana?', 'multiple_choice', NULL, '["A. Clean rainwater","B. Distilled water","C. Untreated sewage","D. Spring water from a protected source"]', 'C', 'Untreated sewage introduces disease-causing organisms and excess nutrients into rivers; clean rainwater, distilled water and protected spring water contain few impurities and are not pollutants. Therefore the correct answer is C: Untreated sewage.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_env_b002_004', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The process of adding chlorine to kill bacteria during water treatment is called', 'multiple_choice', NULL, '["A. filtration","B. sedimentation","C. aeration","D. chlorination"]', 'D', 'Chlorination is the disinfection stage of water treatment in which a controlled dose of chlorine kills remaining bacteria and viruses; filtration removes suspended solids, sedimentation lets heavy particles settle, and aeration adds air to improve taste. Therefore the correct answer is D: chlorination.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_env_b002_005', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Fertilizer run-off from farms enters a lake and causes rapid growth of algae. This process is known as', 'multiple_choice', NULL, '["A. eutrophication","B. evaporation","C. sedimentation","D. neutralisation"]', 'A', 'Nitrates and phosphates from fertilizer are plant nutrients that are normally scarce in natural waters; their sudden input feeds an algal bloom, a process called eutrophication. Evaporation, sedimentation and neutralisation are unrelated physical or chemical processes. Therefore the correct answer is A: eutrophication.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_env_b002_006', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which sequence shows the stages of municipal water treatment in the correct order?', 'multiple_choice', NULL, '["A. Chlorination, filtration, sedimentation, screening","B. Screening, coagulation and sedimentation, filtration, chlorination","C. Filtration, screening, chlorination, sedimentation","D. Sedimentation, chlorination, screening, filtration"]', 'B', 'Raw water is first screened to remove large debris, then alum is added so fine particles clump and settle (coagulation and sedimentation), then sand filters remove remaining solids, and finally chlorine disinfects the clear water before distribution. Therefore the correct answer is B: Screening, coagulation and sedimentation, filtration, chlorination.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_env_b002_007', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Cholera outbreaks in Ghanaian communities are most strongly linked to water that has been polluted by', 'multiple_choice', NULL, '["A. dissolved oxygen from fast-flowing streams","B. harmless clay particles after heavy rain","C. faecal matter from poor sanitation and open defecation","D. chlorine added during treatment"]', 'C', 'Cholera is caused by Vibrio cholerae, which spreads through water contaminated with human faeces; prevention relies on proper latrines, handwashing and boiling or chlorinating drinking water. Dissolved oxygen, clay turbidity and correct chlorination do not transmit cholera. Therefore the correct answer is C: faecal matter from poor sanitation and open defecation.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_env_b002_008', 'topic_wassce_p2_sci_env', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Turbidity in a water sample refers to its', 'multiple_choice', NULL, '["A. temperature measured in the shade","B. hardness caused by dissolved salts","C. acidity measured with litmus paper","D. cloudiness caused by suspended particles"]', 'D', 'Turbidity is the scattering of light by suspended clay, silt and organic particles, which makes water look cloudy; high turbidity can shield microbes from disinfectants, so it is removed by sedimentation and filtration before chlorination. Therefore the correct answer is D: cloudiness caused by suspended particles.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_462_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_462_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_462_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_462_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_462_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_462_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_462_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_462_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_462_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_462_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
